import React from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';
import SignupForm from '../components/signup/SignupForm';
import { Link } from 'react-router-dom';

const Signup = () => {
    return (
        <div className="bg-background text-on-background min-h-screen flex flex-col">
            <Header />

            {/* Main Content */}
            <main className="flex-grow flex items-center justify-center px-margin-mobile pt-10 pb-1">
                <div className="w-full max-w-[500px] flex flex-col gap-1">
                    {/* Signup Card */}
                    <div className="bg-surface-container-lowest border border-outline-variant rounded-lg p-5 md:p-6 shadow-sm">
                        <div className="text-center mb-4">
                            <h1 className="font-headline-lg text-headline-lg text-primary mb-2">Create Account</h1>
                            <p className="font-body-md text-body-md text-on-surface-variant">Complete the form below to set up your account.</p>
                        </div>
                        <SignupForm />
                    </div>

                    {/* Footer Link */}
                    <div className="text-center">
                        <p className="font-body-sm text-body-sm text-on-surface-variant">
                            Already have an account?{' '}
                            <Link to="/login" className="text-secondary font-semibold hover:underline">Log In</Link>
                        </p>
                    </div>
                </div>
            </main>

            <Footer />
        </div>
    );
};

export default Signup;
